// FinanceEngineTests.swift
//
// Loads fixtures.json (generated by generate-fixtures.ts via `npx tsx`) and
// asserts that the Swift FinanceEngine produces outputs within 1e-6 of the
// Node.js reference engine for every test case.
//
// IMPORTANT SEMANTICS (verified against TS source):
//   - savingsRate is a PERCENTAGE (0–100+, can be negative), not a 0–1 fraction.
//   - netWorthOutlook returns horizonMonths+1 points: month 0 = current snapshot,
//     months 1..horizon = forecast. A 60-month horizon produces 61 points.
//   - When healthScore.noData == true, estimatedCreditScore == 0 and all sub-scores == 0.
//   - utilization > 1.0 is valid when totalDebt exceeds totalCreditLimit (over-limit).
//
// Run fixture generation first:
//   cd ios/IncomeTrackerTests/Fixtures/gen && npx tsx generate-fixtures.ts
//
// Then run:
//   xcodebuild test -scheme IncomeTrackerTests -destination 'platform=iOS Simulator,name=iPhone 16'

import XCTest
@testable import IncomeTracker

// MARK: - Codable shims for fixture JSON

/// Maps the JSON structure produced by generate-fixtures.ts.
/// The "output" object may have optional keys depending on the test case.
private struct Fixture: Decodable {
    let testName: String
    let input: FixtureInput
    let output: FixtureOutput
}

private struct FixtureInput: Decodable {
    let month: MonthBudget
    let state: LedgerState
    let accounts: [Account]
    let goals: [SavingsGoal]
    let savingsTarget: Double
    let monthlySurplus: Double?
    let horizonMonths: Int?
    let previousMonth: MonthBudget?
}

private struct FixtureOutput: Decodable {
    let projection: Projection
    let debtSummary: DebtSummary
    let assetSummary: AssetSummary
    let netWorthSummary: NetWorthSummary
    let netWorthOutlook: [NetWorthPoint]?
    let monthlyFlow: [MonthlyFlowPoint]?
    let healthScore: HealthScoreBreakdown?
    let signals: [FinancialSignal]?
    let goalSequence: GoalSequenceResult?
    let seededMonth: MonthBudget?
}

// MARK: - Custom Codable for GoalSequenceResult (flatten perGoal dict)

// The JS engine stores `GoalMonthPoint.perGoal` as a plain JSON object keyed by goal ID.
// The Swift type `GoalMonthPoint` uses `[String: GoalMonthPointPerGoal]` which decodes identically.

// MARK: - Test class

final class FinanceEngineTests: XCTestCase {

    // MARK: - Fixture loading (loaded once per test run)

    // Written once in class setUp() before any test runs, read-only afterwards.
    nonisolated(unsafe) private static var fixtures: [Fixture] = []

    override class func setUp() {
        super.setUp()

        // Resolve path: first look inside the test bundle, then fall back to the
        // source-tree location (useful when running under `xcodebuild` from the project root).
        let path = fixturesPath()
        guard let url = path else {
            XCTFail("fixtures.json not found — run `npx tsx generate-fixtures.ts` in ios/IncomeTrackerTests/Fixtures/gen/")
            return
        }

        do {
            let data = try Data(contentsOf: url)
            let decoder = JSONDecoder()
            fixtures = try decoder.decode([Fixture].self, from: data)
        } catch {
            XCTFail("Failed to load fixtures.json: \(error)")
        }
    }

    // MARK: - Helpers

    private static func fixturesPath() -> URL? {
        // 1. Test bundle resource (works when file is in the Xcode target's Copy Bundle Resources phase)
        if let bundleURL = Bundle(for: FinanceEngineTests.self).url(forResource: "fixtures", withExtension: "json") {
            return bundleURL
        }
        // 2. Source-tree relative path (works when running via xcodebuild from repo root)
        let sourceRelative = #file
            .replacingOccurrences(of: "IncomeTrackerTests/Engine/FinanceEngineTests.swift", with: "")
            .appending("IncomeTrackerTests/Fixtures/data/fixtures.json")
        let url = URL(fileURLWithPath: sourceRelative)
        if FileManager.default.fileExists(atPath: url.path) {
            return url
        }
        return nil
    }

    private func fixture(named name: String) throws -> Fixture {
        guard let f = Self.fixtures.first(where: { $0.testName == name }) else {
            throw XCTSkip("Fixture '\(name)' not found in fixtures.json")
        }
        return f
    }

    /// Assert two doubles are equal within 1e-6.
    private func assertEqual(_ actual: Double, _ expected: Double, _ label: String,
                              file: StaticString = #file, line: UInt = #line) {
        XCTAssertEqual(actual, expected, accuracy: 1e-6,
                       "\(label): got \(actual), expected \(expected)", file: file, line: line)
    }

    // MARK: - testProjection

    func testProjection() throws {
        let testCases = ["empty_month", "basic_month", "debt_heavy", "investment_portfolio",
                         "goals_basic", "health_score_good", "health_score_poor", "seed_from_previous"]

        for name in testCases {
            let fix = try fixture(named: name)
            let actual = FinanceEngine.projection(for: fix.input.month)
            let exp    = fix.output.projection

            assertEqual(actual.monthlyIncome,            exp.monthlyIncome,            "\(name).monthlyIncome")
            assertEqual(actual.monthlyExpenses,          exp.monthlyExpenses,          "\(name).monthlyExpenses")
            assertEqual(actual.monthlySurplus,           exp.monthlySurplus,           "\(name).monthlySurplus")
            assertEqual(actual.recurringMonthlyIncome,   exp.recurringMonthlyIncome,   "\(name).recurringMonthlyIncome")
            assertEqual(actual.recurringMonthlyExpenses, exp.recurringMonthlyExpenses, "\(name).recurringMonthlyExpenses")
            assertEqual(actual.recurringMonthlySurplus,  exp.recurringMonthlySurplus,  "\(name).recurringMonthlySurplus")
            assertEqual(actual.annualIncome,             exp.annualIncome,             "\(name).annualIncome")
            assertEqual(actual.annualExpenses,           exp.annualExpenses,           "\(name).annualExpenses")
            assertEqual(actual.annualSurplus,            exp.annualSurplus,            "\(name).annualSurplus")
            assertEqual(actual.savingsRate,              exp.savingsRate,              "\(name).savingsRate")
            assertEqual(actual.paidTotal,                exp.paidTotal,                "\(name).paidTotal")
            assertEqual(actual.unpaidTotal,              exp.unpaidTotal,              "\(name).unpaidTotal")
            XCTAssertEqual(actual.oneOffCount, exp.oneOffCount, "\(name).oneOffCount")
        }
    }

