    func testDebtSummary() throws {
        let testCases = ["empty_month", "debt_heavy", "health_score_poor", "net_worth_outlook_60"]

        for name in testCases {
            let fix = try fixture(named: name)
            let actual = FinanceEngine.debtSummary(fix.input.accounts)
            let exp    = fix.output.debtSummary

            assertEqual(actual.totalDebt,        exp.totalDebt,        "\(name).totalDebt")
            assertEqual(actual.totalCreditLimit,  exp.totalCreditLimit, "\(name).totalCreditLimit")
            assertEqual(actual.availableCredit,  exp.availableCredit,  "\(name).availableCredit")
            assertEqual(actual.utilization,      exp.utilization,      "\(name).utilization")
            assertEqual(actual.monthlyMinimums,  exp.monthlyMinimums,  "\(name).monthlyMinimums")
            assertEqual(actual.weightedApr,      exp.weightedApr,      "\(name).weightedApr")
            XCTAssertEqual(actual.nextDueDay,    exp.nextDueDay,       "\(name).nextDueDay")
        }
    }

